package com.travelbird.trip.repository.querydsl;
import com.querydsl.core.types.dsl.BooleanExpression; import com.querydsl.jpa.impl.JPAQueryFactory; import com.travelbird.trip.entity.*; import jakarta.persistence.EntityManager; import java.time.LocalDate; import java.util.List; import org.springframework.stereotype.Repository;
@Repository public class TripQueryRepository { private final JPAQueryFactory query; public TripQueryRepository(EntityManager em){query=new JPAQueryFactory(em);}
 public List<Trip> list(Long uid,TripStatus category,Long cursor,int limit,LocalDate today){QTrip t=QTrip.trip;BooleanExpression status=switch(category){case UPCOMING->t.startDate.gt(today);case IN_PROGRESS->t.startDate.loe(today).and(t.endDate.goe(today));case COMPLETED->t.endDate.lt(today);case CANCELLED->t.id.isNull();};return query.selectFrom(t).where(t.userId.eq(uid),t.cancelledAt.isNull(),status,cursor==null?null:t.id.lt(cursor)).orderBy(t.id.desc()).limit(limit).fetch();}
 public List<Trip> calendar(Long uid,LocalDate from,LocalDate to){QTrip t=QTrip.trip;return query.selectFrom(t).where(t.userId.eq(uid),t.cancelledAt.isNull(),t.startDate.loe(to),t.endDate.goe(from)).orderBy(t.startDate.asc(),t.id.asc()).fetch();}}
